// Kernel 1: compute partial sum/sumsq for each (group, partition) block.
// partials layout: [num_groups * P * 2], stride: group*P*2 + p*2 + {0=sum,1=sumsq}
__global__ void partial_stats_kernel(
    const float* __restrict__ input,
    float* __restrict__ partials,
    int64_t num_groups,
    int64_t spatial,
    int P) {

    const int group = blockIdx.x;
    const int p     = blockIdx.y;
    if (group >= num_groups) return;

    const float* in_ptr = input + (int64_t)group * spatial;

    const int64_t chunk   = (spatial + P - 1) / P;
    const int64_t p_start = (int64_t)p * chunk;
    const int64_t p_end   = p_start + chunk < spatial ? p_start + chunk : spatial;

    float local_sum   = 0.0f;
    float local_sumsq = 0.0f;
    for (int64_t i = p_start + threadIdx.x; i < p_end; i += blockDim.x) {
        float v = in_ptr[i];
        local_sum   += v;
        local_sumsq += v * v;
    }

    local_sum   = warp_reduce_sum(local_sum);
    local_sumsq = warp_reduce_sum(local_sumsq);

    extern __shared__ float shared[];
    const int warp_count = blockDim.x >> 5;
    float* wbuf_sum   = shared;
    float* wbuf_sumsq = shared + warp_count;

    const int lane    = threadIdx.x & 31;
    const int warp_id = threadIdx.x >> 5;
    if (lane == 0) {
        wbuf_sum[warp_id]   = local_sum;
        wbuf_sumsq[warp_id] = local_sumsq;
    }
    __syncthreads();

    if (warp_id == 0) {
        float s  = (lane < warp_count) ? wbuf_sum[lane]   : 0.0f;
        float sq = (lane < warp_count) ? wbuf_sumsq[lane] : 0.0f;
        s  = warp_reduce_sum(s);
        sq = warp_reduce_sum(sq);
