    const float* part = partials + (int64_t)group * P * 2;
    float s= (threadIdx.x < P) ? part[threadIdx.x * 2 + 0] : 0.0f;
    float sq = (threadIdx.x < P) ? part[threadIdx.x * 2 + 1] : 0.0f;
    s  = warp_reduce_sum(s);
    sq = warp_reduce_sum(sq);

