    const float scale = shared[1];

    const float* in_ptr  = input  + (int64_t)group * spatial;
    float*       out_ptr = output + (int64_t)group * spatial;
    for (int64_t i = threadIdx.x; i < spatial; i += blockDim.x) {
        out_ptr[i] = (in_ptr[i] - mean) * scale;
    }
